//! Property-based fuzzing of WebSocket sessions with malformed input over real TCP.
//!
//! Each case completes a valid handshake and then writes a generated byte stream: frames
//! with random FIN/RSV bits, reserved opcodes, unmasked client frames, oversized and
//! fragmented control frames, broken fragmentation sequences, invalid UTF-8, bogus 64-bit
//! lengths, invalid close codes and plain garbage. Whatever arrives, the server must:
//!
//! * never panic (`sessions_panicked` stays 0) and never hang a session (every session ends
//!   within a bounded time once the client goes away);
//! * answer protocol violations with a close frame whose code is one that may be sent on
//!   the wire (never 1005/1006/1015 or a reserved code);
//! * keep serving new handshakes.
//!
//! The case count is modest so the suite stays fast; raise it locally with
//! `PROPTEST_CASES=2000 cargo test -p poring-tests --test ws_fuzz`.

use std::net::SocketAddr;
use std::time::{Duration, Instant};

use poring::prelude::*;
use poring::ws::{ManagedSocket, TypedSocket, WebSocketUpgrade};
use proptest::prelude::*;
use proptest::test_runner::{Config, TestRunner};
use serde::{Deserialize, Serialize};
use tokio::io::{AsyncReadExt, AsyncWriteExt};

const KEY: &str = "dGhlIHNhbXBsZSBub25jZQ==";

#[derive(Debug, Deserialize, Serialize, PoringSchema)]
struct Msg {
    #[poring(max_length = 64)]
    text: String,
}

async fn server() -> poring::Server {
    Poring::new()
        .ws("/managed", |ws: WebSocketUpgrade| async move {
            ws.max_message_size(4096)
                .max_frame_size(4096)
                .managed()
                .close_timeout(Duration::from_millis(200))
                .on_upgrade(|mut sock: ManagedSocket| async move {
                    while let Some(m) = sock.recv().await {
                        if sock.send(m).await.is_err() {
                            break;
                        }
                    }
                })
        })
        .ws("/typed", |ws: WebSocketUpgrade| async move {
            ws.max_message_size(4096).typed::<Msg, Msg>().on_upgrade(
                |mut sock: TypedSocket<Msg, Msg>| async move {
                    while let Some(r) = sock.recv().await {
                        if let Ok(m) = r
                            && sock.send(&m).await.is_err()
                        {
                            break;
                        }
                    }
                },
            )
        })
        .ws("/raw", |ws: WebSocketUpgrade| async move {
            ws.max_message_size(4096).on_upgrade(|mut sock| async move {
                use futures_util::{SinkExt, StreamExt};
                while let Some(Ok(m)) = sock.next().await {
                    if m.is_close() || sock.send(m).await.is_err() {
                        break;
                    }
                }
            })
        })
        .build()
        .unwrap()
        .bind("127.0.0.1:0")
        .await
        .unwrap()
}

/// One generated wire element.
#[derive(Clone, Debug)]
enum Piece {
    Frame {
        fin: bool,
        rsv: u8,
        opcode: u8,
        masked: bool,
        payload: Vec<u8>,
    },
    /// A header claiming a huge 64-bit length, then a few bytes.
    BogusLength(u64),
    Garbage(Vec<u8>),
}

fn piece() -> impl Strategy<Value = Piece> {
    let opcode = prop_oneof![
        8 => prop::sample::select(vec![0u8, 1, 2, 8, 9, 10]),
        1 => 0u8..16,
    ];
    let payload = prop_oneof![
        4 => prop::collection::vec(any::<u8>(), 0..32),
        2 => "[a-z]{0,40}".prop_map(|s| format!(r#"{{"text":"{s}"}}"#).into_bytes()),
        1 => Just(vec![0xC3, 0x28]),              // invalid UTF-8
        1 => Just(vec![0x03, 0xED]),              // close code 1005 (must not be sent)
        1 => Just(vec![0x03, 0xE8, 0xFF]),        // 1000 with an invalid UTF-8 reason
        1 => prop::collection::vec(any::<u8>(), 126..300), // > 125: illegal in control frames
    ];
    prop_oneof![
        12 => (any::<bool>(), prop_oneof![9 => Just(0u8), 1 => 0u8..8], opcode,
               prop_oneof![9 => Just(true), 1 => Just(false)], payload)
            .prop_map(|(fin, rsv, opcode, masked, payload)| Piece::Frame { fin, rsv, opcode, masked, payload }),
        1 => (1u64 << 40..u64::MAX).prop_map(Piece::BogusLength),
        1 => prop::collection::vec(any::<u8>(), 1..64).prop_map(Piece::Garbage),
    ]
}

fn encode(p: &Piece, out: &mut Vec<u8>) {
    match p {
        Piece::Frame {
            fin,
            rsv,
            opcode,
            masked,
            payload,
        } => {
            out.push(((*fin as u8) << 7) | (rsv << 4) | opcode);
            let m = (*masked as u8) << 7;
            match payload.len() {
                n if n < 126 => out.push(m | n as u8),
                n if n <= 0xFFFF => {
                    out.push(m | 126);
                    out.extend_from_slice(&(n as u16).to_be_bytes());
                }
                n => {
                    out.push(m | 127);
                    out.extend_from_slice(&(n as u64).to_be_bytes());
                }
            }
            let key = [0x37, 0xFA, 0x21, 0x3D];
            if *masked {
                out.extend_from_slice(&key);
                out.extend(payload.iter().enumerate().map(|(i, b)| b ^ key[i % 4]));
            } else {
                out.extend_from_slice(payload);
            }
        }
        Piece::BogusLength(n) => {
            out.extend_from_slice(&[0x82, 0x80 | 127]);
            out.extend_from_slice(&n.to_be_bytes());
            out.extend_from_slice(&[1, 2, 3, 4, 5, 6, 7, 8]);
        }
        Piece::Garbage(g) => out.extend_from_slice(g),
    }
}

/// Close codes a server may put on the wire (RFC 6455 §7.4).
fn sendable(code: u16) -> bool {
    matches!(code, 1000..=1003 | 1007..=1014 | 3000..=4999)
}

/// Runs one case against `path`: handshake, write the pieces, read whatever comes back for
/// a short while. Returns the close code the server sent, if any.
async fn run_case(addr: SocketAddr, path: &str, pieces: &[Piece]) -> Result<Option<u16>, String> {
    let mut s = tokio::net::TcpStream::connect(addr)
        .await
        .map_err(|e| e.to_string())?;
    let req = format!(
        "GET {path} HTTP/1.1\r\nHost: {addr}\r\nConnection: Upgrade\r\nUpgrade: websocket\r\n\
         Sec-WebSocket-Version: 13\r\nSec-WebSocket-Key: {KEY}\r\n\r\n"
    );
    s.write_all(req.as_bytes())
        .await
        .map_err(|e| e.to_string())?;
    let mut buf = Vec::new();
    let mut chunk = [0u8; 4096];
    let head_end = tokio::time::timeout(Duration::from_secs(5), async {
        loop {
            let n = s.read(&mut chunk).await.unwrap_or(0);
            if n == 0 {
                return None;
            }
            buf.extend_from_slice(&chunk[..n]);
            if let Some(i) = buf.windows(4).position(|w| w == b"\r\n\r\n") {
                return Some(i + 4);
            }
        }
    })
    .await
    .map_err(|_| "handshake timed out".to_owned())?
    .ok_or("closed during handshake")?;
    if !buf.starts_with(b"HTTP/1.1 101") {
        return Err(format!(
            "handshake refused: {}",
            String::from_utf8_lossy(&buf[..head_end])
        ));
    }
    buf.drain(..head_end);
    let mut wire = Vec::new();
    for p in pieces {
        encode(p, &mut wire);
    }
    // The server may close mid-write: that is fine.
    let _ = s.write_all(&wire).await;
    let _ = tokio::time::timeout(Duration::from_millis(300), async {
        loop {
            match s.read(&mut chunk).await {
                Ok(0) | Err(_) => break,
                Ok(n) => buf.extend_from_slice(&chunk[..n]),
            }
        }
    })
    .await;
    // Find a server close frame (unmasked, opcode 8) in what came back.
    let mut i = 0;
    while i + 2 <= buf.len() {
        let opcode = buf[i] & 0x0F;
        let len = (buf[i + 1] & 0x7F) as usize;
        let (hdr, len) = match len {
            126 if i + 4 <= buf.len() => (4, u16::from_be_bytes([buf[i + 2], buf[i + 3]]) as usize),
            127 => break,
            126 => break,
            n => (2, n),
        };
        if opcode == 8 {
            if len >= 2 && i + hdr + 2 <= buf.len() {
                return Ok(Some(u16::from_be_bytes([buf[i + hdr], buf[i + hdr + 1]])));
            }
            return Ok(None);
        }
        i += hdr + len;
    }
    Ok(None)
}

#[test]
fn malformed_websocket_input_never_panics_hangs_or_sends_reserved_codes() {
    let rt = tokio::runtime::Builder::new_multi_thread()
        .worker_threads(2)
        .enable_all()
        .build()
        .unwrap();
    let server = rt.block_on(server());
    let addr = server.local_addr();
    let cases = std::env::var("PROPTEST_CASES")
        .ok()
        .and_then(|v| v.parse().ok())
        .unwrap_or(96);
    let mut runner = TestRunner::new(Config {
        cases,
        failure_persistence: None,
        ..Config::default()
    });
    let strategy = (
        prop::sample::select(vec!["/managed", "/typed", "/raw"]),
        prop::collection::vec(piece(), 1..12),
    );
    let result = runner.run(&strategy, |(path, pieces)| {
        let code = rt
            .block_on(run_case(addr, path, &pieces))
            .map_err(TestCaseError::fail)?;
        if let Some(code) = code {
            // Raw sockets send whatever the application sends; Poring's managed and typed
            // sessions must keep reserved codes off the wire.
            if path != "/raw" {
                prop_assert!(sendable(code), "{path} sent close code {code}");
            }
        }
        Ok(())
    });
    if let Err(e) = result {
        panic!("{e}");
    }
    // Every session ends once its client is gone; nothing panicked.
    let deadline = Instant::now() + Duration::from_secs(15);
    loop {
        let stats = server.ws_stats();
        if stats.active_sessions == 0 {
            assert_eq!(stats.sessions_panicked, 0, "{stats:?}");
            assert_eq!(stats.handshakes_accepted, stats.sessions_ended, "{stats:?}");
            break;
        }
        assert!(
            Instant::now() < deadline,
            "sessions still active: {stats:?}"
        );
        std::thread::sleep(Duration::from_millis(20));
    }
    // And the server still accepts work.
    let ok = rt.block_on(run_case(addr, "/managed", &[]));
    assert!(ok.is_ok(), "{ok:?}");
    rt.block_on(server.shutdown()).unwrap();
}
